package edu.uow.csit314.idp;
import com.fasterxml.jackson.databind.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.*;
import org.springframework.transaction.annotation.Transactional;
import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PlatformIntegrationTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;
 record Client(MockHttpSession session,String csrf){}
 Client client()throws Exception{MvcResult r=mvc.perform(get("/api/auth/csrf")).andExpect(status().isOk()).andReturn();return new Client((MockHttpSession)r.getRequest().getSession(),read(r).get("token").asText());}
 JsonNode read(MvcResult r)throws Exception{return json.readTree(r.getResponse().getContentAsString());}
 ResultActions postJson(Client c,String path,Object body)throws Exception{return mvc.perform(post(path).session(c.session()).header("X-CSRF-Token",c.csrf()).contentType("application/json").content(json.writeValueAsString(body)));}
 ResultActions putJson(Client c,String path,Object body)throws Exception{return mvc.perform(put(path).session(c.session()).header("X-CSRF-Token",c.csrf()).contentType("application/json").content(json.writeValueAsString(body)));}
 ResultActions patchJson(Client c,String path)throws Exception{return mvc.perform(patch(path).session(c.session()).header("X-CSRF-Token",c.csrf()).contentType("application/json").content("{}"));}
 ResultActions deleteJson(Client c,String path)throws Exception{return mvc.perform(delete(path).session(c.session()).header("X-CSRF-Token",c.csrf()));}
 Client login(String email,String role)throws Exception{Client c=client();postJson(c,"/api/auth/login",Map.of("email",email,"password","Demo123!","workspace",role)).andExpect(status().isOk()).andExpect(jsonPath("$.activeRole").value(role));return c;}
 JsonNode getJson(Client c,String path)throws Exception{return read(mvc.perform(get(path).session(c.session())).andExpect(status().isOk()).andReturn());}
 Map<String,Object> project(long company,long category){return new HashMap<>(Map.of("title","Test home","companyId",company,"categoryId",category,"stage","CURRENT","propertyType","HDB","location","Singapore","budget",50000,"area",100,"progress",20));}
 @Test void csrfAndRoleBoundariesAreEnforced()throws Exception{mvc.perform(post("/api/auth/login").contentType("application/json").content("{}")).andExpect(status().isForbidden());Client customer=login("alex@forma.demo","CUSTOMER");mvc.perform(get("/api/accounts").session(customer.session())).andExpect(status().isForbidden());postJson(customer,"/api/categories",Map.of("name","Forbidden","active",true)).andExpect(status().isForbidden());postJson(customer,"/api/auth/workspace",Map.of("workspace","USER_ADMIN")).andExpect(status().isForbidden());assertThat(getJson(customer,"/api/projects").size()).isEqualTo(6);}
 @Test void namedTeamAccountsUseAssignedWorkspaces()throws Exception{Client c=client();JsonNode team=getJson(c,"/api/auth/demo-users");assertThat(team.size()).isEqualTo(6);for(JsonNode u:team)for(JsonNode role:u.get("roles"))postJson(c,"/api/auth/login",Map.of("email",u.get("email").asText(),"password","Demo123!","workspace",role.asText())).andExpect(status().isOk()).andExpect(jsonPath("$.activeRole").value(role.asText()));assertThat(team.toString()).doesNotContain("passwordHash");}
 @Test void signupRequiresAdminApprovalAndNeverAllowsSelfAssignedAdmin()throws Exception{Client applicant=client();Map<String,Object> d=new HashMap<>(Map.of("name","New Customer","email","signup@forma.test","role","CUSTOMER","password","SignupPass123!","confirmPassword","SignupPass123!"));Map<String,Object> bad=new HashMap<>(d);bad.put("role","USER_ADMIN");postJson(applicant,"/api/auth/signup",bad).andExpect(status().isBadRequest());long id=read(postJson(applicant,"/api/auth/signup",d).andExpect(status().isCreated()).andReturn()).get("id").asLong();postJson(applicant,"/api/auth/login",Map.of("email",d.get("email"),"password",d.get("password"))).andExpect(status().isUnauthorized());Client manager=login("manager@forma.demo","PLATFORM_MANAGER");postJson(manager,"/api/registrations/"+id+"/approve",Map.of("role","CUSTOMER")).andExpect(status().isForbidden());Client admin=login("admin@forma.demo","USER_ADMIN");assertThat(getJson(admin,"/api/registrations").toString()).doesNotContain("passwordHash","requesterTokenHash");postJson(admin,"/api/registrations/"+id+"/approve",Map.of("role","USER_ADMIN")).andExpect(status().isBadRequest());postJson(admin,"/api/registrations/"+id+"/approve",Map.of("role","CUSTOMER")).andExpect(status().isOk());postJson(applicant,"/api/auth/login",Map.of("email",d.get("email"),"password",d.get("password"))).andExpect(status().isOk()).andExpect(jsonPath("$.profile.name").value("New Customer"));postJson(admin,"/api/registrations/"+id+"/approve",Map.of("role","CUSTOMER")).andExpect(status().isConflict());}
 @Test void profilesAndAccountsHaveSeparateLifecycles()throws Exception{Client admin=login("admin@forma.demo","USER_ADMIN");int before=getJson(admin,"/api/accounts").size();long profile=read(postJson(admin,"/api/profiles",Map.of("name","Profile only","email","profile@forma.test")).andExpect(status().isOk()).andReturn()).get("id").asLong();assertThat(getJson(admin,"/api/accounts").size()).isEqualTo(before);long account=read(postJson(admin,"/api/accounts",Map.of("email","account@forma.test","password","AccountPass123!","defaultRole","CUSTOMER","roles",List.of("CUSTOMER"),"profileId",profile)).andExpect(status().isOk()).andReturn()).get("id").asLong();putJson(admin,"/api/profiles/"+profile,Map.of("name","Updated contact","email","contact@forma.test")).andExpect(status().isOk());assertThat(getJson(admin,"/api/accounts/"+account).get("email").asText()).isEqualTo("account@forma.test");deleteJson(admin,"/api/profiles/"+profile).andExpect(status().isOk());assertThat(getJson(admin,"/api/accounts/"+account).get("profile").isNull()).isTrue();}
 @Test void suspensionAndRestoreDoNotReviveOldSessions()throws Exception{Client admin=login("admin@forma.demo","USER_ADMIN");long id=read(postJson(admin,"/api/accounts",Map.of("email","suspend@forma.test","name","Suspension test","password","SuspendPass123!","defaultRole","CUSTOMER")).andExpect(status().isOk()).andReturn()).get("id").asLong();Client customer=client();postJson(customer,"/api/auth/login",Map.of("email","suspend@forma.test","password","SuspendPass123!")).andExpect(status().isOk());patchJson(admin,"/api/accounts/"+id+"/suspension").andExpect(status().isOk());mvc.perform(get("/api/favourites").session(customer.session())).andExpect(status().isUnauthorized());patchJson(admin,"/api/accounts/"+id+"/suspension").andExpect(status().isOk());mvc.perform(get("/api/favourites").session(customer.session())).andExpect(status().isUnauthorized());postJson(customer,"/api/auth/login",Map.of("email","suspend@forma.test","password","SuspendPass123!")).andExpect(status().isOk());long self=getJson(admin,"/api/auth/me").get("id").asLong();patchJson(admin,"/api/accounts/"+self+"/suspension").andExpect(status().isBadRequest());}
 @Test void designerOwnershipAndLinkedCategoryIntegrityAreEnforced()throws Exception{Client crystal=login("designer@forma.demo","DESIGNER"),yj=login("liao.yijou@forma.demo","DESIGNER"),manager=login("manager@forma.demo","PLATFORM_MANAGER");JsonNode existing=getJson(crystal,"/api/projects?mine=true").get(0);Map<String,Object> p=project(existing.get("companyId").asLong(),existing.get("categoryId").asLong());putJson(yj,"/api/projects/"+existing.get("id").asLong(),p).andExpect(status().isForbidden());long company=read(postJson(yj,"/api/companies",Map.of("name","YJ test studio","email","yjstudio@forma.test")).andExpect(status().isOk()).andReturn()).get("id").asLong();p.put("companyId",company);long id=read(postJson(yj,"/api/projects",p).andExpect(status().isOk()).andReturn()).get("id").asLong();p.put("stage","PAST");putJson(yj,"/api/projects/"+id,p).andExpect(status().isOk()).andExpect(jsonPath("$.progress").value(100));deleteJson(yj,"/api/companies/"+company).andExpect(status().isConflict());long category=existing.get("categoryId").asLong();putJson(manager,"/api/categories/"+category,Map.of("name","Renamed test category","description","Updated","active",true)).andExpect(status().isOk());assertThat(getJson(yj,"/api/projects/"+id).get("category").asText()).isEqualTo("Renamed test category");deleteJson(manager,"/api/categories/"+category).andExpect(status().isConflict());deleteJson(yj,"/api/projects/"+id).andExpect(status().isOk());deleteJson(yj,"/api/companies/"+company).andExpect(status().isOk());}
 @Test void shortlistsViewsAndReportsReadPersistedActivity()throws Exception{Client customer=login("alex@forma.demo","CUSTOMER"),designer=login("designer@forma.demo","DESIGNER"),manager=login("manager@forma.demo","PLATFORM_MANAGER");JsonNode first=getJson(customer,"/api/projects").get(0);long id=first.get("id").asLong();assertThat(getJson(customer,"/api/companies/"+first.get("companyId").asLong()+"/public").get("name").asText()).isEqualTo("Studio North");mvc.perform(get("/api/reports/daily").session(customer.session())).andExpect(status().isForbidden());postJson(customer,"/api/favourites/"+id,Map.of()).andExpect(status().isOk());postJson(customer,"/api/favourites/"+id,Map.of()).andExpect(status().isOk()).andExpect(jsonPath("$.shortlists").value(1));postJson(customer,"/api/projects/"+id+"/views",Map.of()).andExpect(status().isOk()).andExpect(jsonPath("$.views").value(1));assertThat(getJson(customer,"/api/favourites").size()).isEqualTo(1);JsonNode metrics=getJson(designer,"/api/projects/metrics");assertThat(metrics.toString()).contains("\"views\":1");for(String period:List.of("daily","weekly","monthly")){JsonNode report=getJson(manager,"/api/reports/"+period);assertThat(report.get("projectViews").asLong()).isEqualTo(1);assertThat(report.get("shortlistAdds").asLong()).isEqualTo(1);}mvc.perform(get("/api/reports/daily/export").session(manager.session())).andExpect(status().isOk()).andExpect(content().contentTypeCompatibleWith("text/csv"));deleteJson(customer,"/api/favourites/"+id).andExpect(status().isOk());assertThat(getJson(customer,"/api/favourites").size()).isZero();postJson(customer,"/api/auth/logout",Map.of()).andExpect(status().isOk());}
}
